import { calendarChannel } from "@/lib/booking";
import { redis } from "@/lib/redis";
import { getSession } from "@/lib/session";

export const dynamic = "force-dynamic";

// SSE stream of calendar changes for the admin UI.
// Each connection gets its own Redis subscriber (a subscribing connection
// can't run other commands).
export async function GET(request: Request) {
  const session = await getSession();
  if (!session) return new Response("unauthorized", { status: 401 });

  const sub = redis().duplicate();
  const encoder = new TextEncoder();
  let heartbeat: ReturnType<typeof setInterval> | undefined;

  const close = () => {
    clearInterval(heartbeat);
    sub.disconnect();
  };
  request.signal.addEventListener("abort", close);

  const stream = new ReadableStream({
    async start(controller) {
      const send = (chunk: string) => controller.enqueue(encoder.encode(chunk));
      sub.on("message", (_channel, message) => send(`data: ${message}\n\n`));
      await sub.subscribe(calendarChannel(session.businessId)).catch((err) => {
        close();
        throw err;
      });
      send(`event: hello\ndata: {}\n\n`);
      heartbeat = setInterval(() => send(`: ping\n\n`), 25_000);
    },
    cancel: close,
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
    },
  });
}
